  "implementation": "def solve(case):
    word_token_indices = case['word_token_indices']
    word_labels = case['word_labels']
    token_count = case['token_count']

    # Initialize token labels with zeros
    token_labels = [0] * token_count

    # Broadcast word labels to each token index
    for i, indices in enumerate(word_token_indices):
        label = word_labels[i]
        for idx in indices:
            token_labels[idx] = label

    # Gather indices where label == 1
    kept_indices = [i for i, lbl in enumerate(token_labels) if lbl == 1]

    return {
        'kept_indices': kept_indices,
        'token_labels': token_labels
    }"
}
